   756→        function copyResults() {
   757→            let resultText = "RCRP Decision Toolkit\n";
   758→            resultText += "=" + "=".repeat(21) + "\n\n";
   759→            
   760→            // Add all answered questions
   761→            const answeredQuestions = Object.keys(answers).sort();
   762→            answeredQuestions.forEach(questionKey => {
   763→                const questionNum = questionKey.replace('q', '');
   764→                const questionText = questionTexts[questionNum];
   765→                const answer = answers[questionKey].toUpperCase();
   766→                resultText += `Q: ${questionText}\n`;
   767→                resultText += `A: ${answer}\n\n`;
   768→            });
   769→            
   770→            // Add outcome
   771→            const outcomeText = document.getElementById('outcome-display').textContent;
   772→            resultText += `OUTCOME: ${outcomeText}\n\n`;
   773→            
   774→            // Add timestamp
   775→            const now = new Date();
   776→            resultText += `Generated: ${now.toLocaleString()}\n`;
   777→            
   778→            // Copy to clipboard
   779→            navigator.clipboard.writeText(resultText).then(() => {
   780→                document.getElementById('copySuccess').style.display = 'block';
   781→                setTimeout(() => {
   782→                    document.getElementById('copySuccess').style.display = 'none';
   783→                }, 3000);
   784→            }).catch(err => {
   785→                // Fallback for older browsers
   786→                const textArea = document.createElement('textarea');
   787→                textArea.value = resultText;
   788→                document.body.appendChild(textArea);
   789→                textArea.select();
   790→                document.execCommand('copy');
   791→                document.body.removeChild(textArea);
   792→                
   793→                document.getElementById('copySuccess').style.display = 'block';
   794→                setTimeout(() => {
   795→                    document.getElementById('copySuccess').style.display = 'none';
   796→                }, 3000);
   797→            });
   798→        }
